SELECT COALESCE(SUM(metric_value), 0)
FROM habit_log
WHERE user_id = #{userId} AND system_code = #{systemCode}
  AND log_date BETWEEN #{from} AND #{to}

SELECT COUNT(*)
FROM habit_log
WHERE user_id = #{userId} AND system_code = #{systemCode}
  AND done = TRUE AND log_date BETWEEN #{from} AND #{to}
